BEGIN;
CREATE TABLE IF NOT EXISTS monitored_sites (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, external_id TEXT NOT NULL, name TEXT NOT NULL, geometry_reference TEXT, created_by BIGINT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(tenant_id,external_id));
CREATE TABLE IF NOT EXISTS monitored_devices (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, site_id BIGINT REFERENCES monitored_sites(id), external_id TEXT NOT NULL, calibration_version TEXT NOT NULL, calibration_due_at TIMESTAMPTZ, credential_fingerprint TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(tenant_id,external_id));
CREATE TABLE IF NOT EXISTS governed_observations (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, site_external_id TEXT NOT NULL, device_external_id TEXT NOT NULL, source_id TEXT, observed_at TIMESTAMPTZ NOT NULL, value DOUBLE PRECISION NOT NULL, unit TEXT NOT NULL, calibration_version TEXT NOT NULL, outlier BOOLEAN NOT NULL, state TEXT NOT NULL DEFAULT 'observed', correction_of BIGINT REFERENCES governed_observations(id), correction_reason TEXT, idempotency_key TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS environmental_investigations (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, observation_id BIGINT REFERENCES governed_observations(id), threshold_version TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'alert_open', assignee_id BIGINT, report_reference TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS environmental_custody_audit (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, observation_id BIGINT REFERENCES governed_observations(id), actor_id BIGINT, action TEXT NOT NULL, details JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS governed_observations_tenant_time_idx ON governed_observations(tenant_id,site_external_id,observed_at DESC);
COMMIT;
